-- ADR-0095 (WP-C1, expand step): chat without class and study_group channels and without the class level of the
-- chat policy (platform → tenant → school). Code stops creating and resolving them; the CHECK values stay until WP-R
-- removes them once no row (soft-deleted included) carries them. Messages of an archived channel are kept (moderation
-- evidence, R25).
-- The backfill runs as the table owner across every tenant: FORCE ROW LEVEL SECURITY is lifted for this transaction
-- only and restored below (the application roles never bypass RLS).
ALTER TABLE chat.channels NO FORCE ROW LEVEL SECURITY;
ALTER TABLE chat.chat_policies NO FORCE ROW LEVEL SECURITY;

-- ---------- class / study_group channels: archived (R21 soft-delete, never DELETE) ----------
UPDATE chat.channels SET deleted_at = now(), delete_reason = 'adr0095_class_removed', updated_at = now(), version = version + 1
  WHERE channel_type IN ('class', 'study_group') AND deleted_at IS NULL;

-- ---------- chat_policies of the class level: soft-deleted ----------
UPDATE chat.chat_policies SET deleted_at = now(), delete_reason = 'adr0095_class_removed', updated_at = now(), version = version + 1
  WHERE scope_type = 'class' AND deleted_at IS NULL;

